    {
      "activity_id": "ACT-3",
      "activity_name": "U3-U5: Framework & Extension Dependency Upgrades",
      "activity_description": "Update dependencies to Spring Integration 4.1.5, SI Kafka 1.2.0, and Spring Hadoop 2.2.0 GA across build manifests, resolving breaking API changes and ensuring existing unit/integration tests pass.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "ACT-4",
      "activity_name": "U6: Expose Module and Container Identifiers to Components",
      "activity_description": "Implement mechanism to inject runtime container ID and module ID into module environment contexts and execution headers for logging purposes.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "ACT-5",
      "activity_name": "U7: Kafka Bus Default & Property Overrides Implementation",
      "activity_description": "Add support for fine-grained Kafka consumer (autoCommitEnabled, queueSize, maxWait, fetchSize) and producer (batchSize, batchTimeout) settings override via deployment properties.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "ACT-6",
      "activity_name": "U8: RPM Build Script Consolidation",
      "activity_description": "Unify Spring XD core and Ambari integration RPM creation scripts into a single repository and verify unified build scripts.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "ACT-7",
